package tech.wenisch.smtp2x.service;
import java.io.IOException; import java.nio.file.*; import java.time.*; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import tech.wenisch.smtp2x.config.Smtp2xProperties; import tech.wenisch.smtp2x.repository.*;
@Service public class RetentionService {private final InboundMessageRepository messages;private final AuditEventRepository audits;private final Smtp2xProperties properties;private final AuditService audit;public RetentionService(InboundMessageRepository m,AuditEventRepository a,Smtp2xProperties p,AuditService au){messages=m;audits=a;properties=p;audit=au;}@Scheduled(cron="${smtp2x.retention.cron:0 20 3 * * *}")@Transactional public void clean(){int content=0;for(var m:messages.findByReceivedAtBefore(Instant.now().minus(Duration.ofDays(properties.retention().contentDays())))){try{Path root=Path.of(m.getContentPath()).getParent();if(root!=null)try(var paths=Files.walk(root)){paths.sorted(java.util.Comparator.reverseOrder()).forEach(p->{try{Files.deleteIfExists(p);}catch(IOException ignored){}});}messages.delete(m);content++;}catch(Exception ignored){}}audits.deleteAll(audits.findByOccurredAtBefore(Instant.now().minus(Duration.ofDays(properties.retention().auditDays()))));audit.record("system","RETENTION_CLEANUP","system","retention","messages="+content);}}
